export enum GameState {
  LOBBY,
  MATCHMAKING,
  IN_GAME,
  POST_MATCH
}

export class GameStateManager {
  private currentState: GameState = GameState.LOBBY;
  private stateListeners: ((newState: GameState, oldState: GameState) => void)[] = [];

  public getCurrentState(): GameState {
    return this.currentState;
  }

  public addStateListener(listener: (newState: GameState, oldState: GameState) => void): void {
    this.stateListeners.push(listener);
  }

  public transitionTo(newState: GameState): void {
    const oldState = this.currentState;
    if (oldState === newState) {
      return;
    }
    this.currentState = newState;
    for (const listener of this.stateListeners) {
      listener(newState, oldState);
    }
    console.log(`GameState transitioned from ${GameState[oldState]} to ${GameState[newState]}`);
  }
}

export class GlobalEventBus {
  private eventListeners: Map<string, Array<(...args: any[]) => void>> = new Map();

  public addEventListener(eventName: string, listener: (...args: any[]) => void): void {
    if (!this.eventListeners.has(eventName)) {
      this.eventListeners.set(eventName, []);
    }
    this.eventListeners.get(eventName)!.push(listener);
  }

  public removeEventListener(eventName: string, listener: (...args: any[]) => void): void {
    const listeners = this.eventListeners.get(eventName);
    if (listeners) {
      const index = listeners.indexOf(listener);
      if (index > -1) {
        listeners.splice(index, 1);
      }
    }
  }

  public triggerEvent(eventName: string, ...args: any[]): void {
    const listeners = this.eventListeners.get(eventName);
    if (listeners) {
      for (const listener of listeners) {
        listener(...args);
      }
    }
  }
}

export interface SaveData {
  PlayerName: string;
  AccountLevel: number;
  BP_Balance: number;
  Diamond_Balance: number;
  OwnedHeroes: string[];
  Settings: {
    AudioVol: number;
    Sensitivity: number;
  };
}

export class SaveSystem {
  private static instance: SaveSystem;
  private readonly STORAGE_KEY = 'game_save_data';

  private constructor() {}

  public static getInstance(): SaveSystem {
    if (!SaveSystem.instance) {
      SaveSystem.instance = new SaveSystem();
    }
    return SaveSystem.instance;
  }

  public load(): SaveData {
    try {
      const data = localStorage.getItem(this.STORAGE_KEY);
      if (data) {
        return JSON.parse(data);
      }
    } catch (error) {
      console.error('Failed to load save data:', error);
    }
    // Return default save data
    return {
      PlayerName: '',
      AccountLevel: 1,
      BP_Balance: 0,
      Diamond_Balance: 0,
      OwnedHeroes: [],
      Settings: {
        AudioVol: 1.0,
        Sensitivity: 1.0,
      },
    };
  }

  public save(data: SaveData): void {
    try {
      localStorage.setItem(this.STORAGE_KEY, JSON.stringify(data));
      console.log('Game saved successfully');
    } catch (error) {
      console.error('Failed to save game:', error);
    }
  }

  public reset(): void {
    localStorage.removeItem(this.STORAGE_KEY);
    console.log('Game data reset');
  }
}

